'use client'

/**
 * Inline single-color provider marks for the in-chat permission card and
 * any other surface that wants to show "who's about to spend your money."
 *
 * Why inline React SVGs instead of <img src="...svg"> or a CSS mask?
 *   - mask-image rasterizes at the displayed size; at 11-14px on a Retina
 *     screen the brand silhouettes (Gemini gradient, HeyGen embedded PNG,
 *     Kling layered curves) came out visibly pixelated.
 *   - <img src="..."> can't inherit `currentColor`, so theme-switching
 *     (dark / light / sepia) wouldn't recolor the icons.
 *   - Inline SVG with `fill="currentColor"` paints from the parent CSS
 *     `color`, renders sharp at any size, and works with the same
 *     `var(--color-text-primary)` token the surrounding header text uses.
 *
 * Paths: extracted from the original brand SVGs and stripped of every
 * brand-specific gradient / fill so the silhouette renders as a single
 * monochrome shape. HeyGen's source is a raster PNG embedded in an SVG,
 * so the mark below is a hand-rolled stylized "H" that reads at icon
 * size — close enough to the brand for an in-chat permission glyph
 * without baking the original raster.
 */

import type { SVGProps } from 'react'

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

const baseProps = (size: number, rest: SVGProps<SVGSVGElement>): SVGProps<SVGSVGElement> => ({
  width: size,
  height: size,
  fill: 'currentColor',
  xmlns: 'http://www.w3.org/2000/svg',
  ...rest,
})

