// ── Dispatcher ───────────────────────────────────────────────────────────────

export type ProviderIconName =
  | 'ollama'
  | 'openai'
  | 'deepmind'
  | 'gemini'
  | 'runway'
  | 'bytedance'
  | 'midjourney'
  | 'fal'
  | 'kling'
  | 'heygen'

const REGISTRY: Record<ProviderIconName, (props: IconProps) => JSX.Element> = {
  ollama: OllamaIcon,
  openai: OpenAIIcon,
  deepmind: DeepMindIcon,
  gemini: GeminiIcon,
  runway: RunwayIcon,
  bytedance: ByteDanceIcon,
  midjourney: MidjourneyIcon,
  fal: FalIcon,
  kling: KlingIcon,
  heygen: HeyGenIcon,
}

/**
 * Resolve which provider mark to render for an `(api, provider)` pair.
 * Returns `null` when no mapping fits — caller should fall back to a
 * neutral lucide icon.
 *
 * The `provider` arg takes precedence: when the user picks a different
 * model from the in-card pill (e.g. switches Veo 3 → Kling), the icon
 * needs to change too. The api fallback only runs when the provider
 * doesn't match a known model id.
 */
export function pickProviderIconName(api: string, provider?: string | null): ProviderIconName | null {
  const p = (provider ?? '').toLowerCase()

  // Provider-id wins. Same identifiers used as model ids in
  // availableProviders[].id, so switching the pill swaps the icon.
  if (p === 'ollama' || p.includes('ollama') || p.includes('local')) return 'ollama'
  if (p === 'veo3' || p === 'deepmind' || p === 'google-deepmind') return 'deepmind'
  if (p === 'heygen') return 'heygen'
  if (p === 'kling') return 'kling'
  if (p === 'runway') return 'runway'
  if (p === 'fal' || p === 'falai' || p.includes('fal-')) return 'fal'
  if (p === 'openai' || p.includes('dall') || p === 'gpt-image') return 'openai'
  if (p === 'google' || p === 'gemini' || p === 'imagen' || p === 'googletts') return 'gemini'
  if (p === 'midjourney' || p === 'mj') return 'midjourney'
  if (p === 'bytedance' || p === 'seedream') return 'bytedance'

  // API fallback for cases where provider isn't set or doesn't map.
  switch (api) {
    case 'veo3':
      return 'deepmind'
    case 'heygen':
      return 'heygen'
    case 'kling':
      return 'kling'
    case 'runway':
      return 'runway'
    case 'falAvatar':
      return 'fal'
    case 'openaiTts':
      return 'openai'
    case 'googleTts':
    case 'googleImageGen':
    case 'geminiTts':
      return 'gemini'
    case 'imageGen':
      return 'fal'
    default:
      return null
  }
}

export function ProviderIcon({ name, size = 14, className, ...rest }: IconProps & { name: ProviderIconName }) {
  const Cmp = REGISTRY[name]
  if (!Cmp) return null
  return <Cmp size={size} className={className} {...rest} />
}
